 public static class SelfTests {
  static List<string> lines=new List<string>();
  static void Check(bool ok,string label){if(!ok)throw new Exception("FAIL: "+label);lines.Add("PASS: "+label);}
  static Book Dummy(int count){return new Book{Id="test",Title="test",Pages=Enumerable.Range(0,count).Select(i=>new Page{Path="page"+i,Width=600,Height=900}).ToList()};}
  static void Art(string path,int number,int width,int height,Color color){
   var v=new DrawingVisual();using(var d=v.RenderOpen()){
    d.DrawRectangle(new SolidColorBrush(color),null,new Rect(0,0,width,height));
    d.DrawEllipse(new SolidColorBrush(Color.FromArgb(45,255,255,255)),null,new Point(width*.8,height*.35),width*.7,width*.7);
    d.DrawRectangle(new SolidColorBrush(Color.FromArgb(40,0,0,0)),null,new Rect(width*.12,height*.55,width*.76,height*.32));
    var face=new Typeface("Microsoft YaHei UI");d.DrawText(new FormattedText("LEAF / DEMO",System.Globalization.CultureInfo.InvariantCulture,FlowDirection.LeftToRight,face,Math.Max(16,width*.043),Brushes.White,1),new Point(width*.09,height*.08));
    d.DrawText(new FormattedText(number.ToString("00"),System.Globalization.CultureInfo.InvariantCulture,FlowDirection.LeftToRight,face,width*.33,Brushes.White,1),new Point(width*.08,height*.22));
    d.DrawText(new FormattedText("阅读测试\n"+width+" × "+height,System.Globalization.CultureInfo.InvariantCulture,FlowDirection.LeftToRight,face,width*.052,Brushes.White,1),new Point(width*.18,height*.64));
   }var bitmap=new RenderTargetBitmap(width,height,96,96,PixelFormats.Pbgra32);bitmap.Render(v);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using(var s=File.Create(path))png.Save(s);
  }
  static void Screenshot(MainWindow window,string path){window.UpdateLayout();var content=(FrameworkElement)window.Content;var bitmap=new RenderTargetBitmap((int)content.ActualWidth,(int)content.ActualHeight,96,96,PixelFormats.Pbgra32);bitmap.Render(content);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using(var s=File.Create(path))png.Save(s);}
  static void Key(MainWindow window,System.Windows.Input.Key key){var source=PresentationSource.FromVisual(window);var e=new KeyEventArgs(Keyboard.PrimaryDevice,source,Environment.TickCount,key){RoutedEvent=Keyboard.PreviewKeyDownEvent};window.RaiseEvent(e);Check(e.Handled,"keyboard handled "+key);}
  public static async Task<int> Run(string directory){
