    Book book=Dummy(20);Check(Paging.Count(book,0,1,true,true)==1,"cover stays single");Check(Paging.Count(book,1,1,true,true)==2,"two portrait pages form spread");Check(Paging.Next(book,10,1,true,true)==12,"11-12 advances to 13-14");
    int adjusted=10+1;Check(adjusted==11&&Paging.Count(book,adjusted,1,true,true)==2,"nudge 11-12 to 12-13");Check(Paging.Next(book,adjusted,1,true,true)==13,"adjusted spread advances to 14-15");Check(Paging.Previous(book,13,1,true,true)==11,"reverse preserves adjusted pair");
    Check(Paging.Next(book,18,1,true,true)==18,"last complete spread does not repeat its final page");Check(Paging.Previous(book,0,1,true,true)==0,"first boundary clamp");
    book.Pages[4].Width=1800;Check(Paging.Count(book,4,2,true,true)==1,"landscape image alone in RTL");Check(Paging.Count(book,3,1,true,true)==1,"portrait before wide image remains single");Check(Paging.Count(book,4,1,false,false)==2,"automatic landscape detection can be disabled");Check(Paging.Count(book,2,0,true,true)==1,"standard mode one image");
