      while(true){starts.Add(p);int n=Paging.Count(sample,p,1,true,true,anchor);for(int j=0;j<n;j++)visited.Add(p+j);int next=Paging.Next(sample,p,1,true,true,anchor);if(next==p)break;p=next;}
      walks &= visited.SequenceEqual(Enumerable.Range(0,length));for(int j=starts.Count-1;j>0;j--)walks &= Paging.Previous(sample,starts[j],1,true,true,anchor)==starts[j-1];
     }
    }Check(walks,"630 pairing walks cover each page once and reverse exactly, including manual anchors and landscape pages");
