    for(int i=1;i<=5;i++)Art(Path.Combine(nested,i+".png"),i,600,i==3?2600:1000,Color.FromRgb(68,(byte)(68+i*10),(byte)(105+i*12)));
    string zipPath=Path.Combine(root,"03 雨后的城市.cbz");if(File.Exists(zipPath))File.Delete(zipPath);using(var zip=ZipFile.Open(zipPath,ZipArchiveMode.Create)){zip.CreateEntryFromFile(Path.Combine(alpha,"2.png"),"chapter/2.png");zip.CreateEntryFromFile(Path.Combine(alpha,"10.png"),"chapter/10.png");zip.CreateEntryFromFile(Path.Combine(alpha,"1.png"),"chapter/1.png");}
    Directory.SetCreationTimeUtc(alpha,new DateTime(2022,1,1,0,0,0,DateTimeKind.Utc));Directory.SetCreationTimeUtc(nested,new DateTime(2020,1,1,0,0,0,DateTimeKind.Utc));File.SetCreationTimeUtc(zipPath,new DateTime(2021,1,1,0,0,0,DateTimeKind.Utc));
    var scan=Library.Scan(new[]{root,alpha});Check(scan.Books.Count==3,"recursive scan, archives, overlapping roots deduplicated, empty folders ignored");var a=scan.Books.First(b=>b.Id==alpha);Check(a.Pages[0].Name=="1.png"&&a.Pages[9].Name=="10.png","cover and pages use natural filename order");
    Check(Library.ByCreated(scan.Books,true).Select(b=>b.Id).SequenceEqual(new[]{alpha,zipPath,nested}),"creation descending uses folder and archive filesystem timestamps");
    Check(Library.ByCreated(scan.Books,false).Select(b=>b.Id).SequenceEqual(new[]{nested,zipPath,alpha}),"creation ascending uses folder and archive filesystem timestamps");
    var ties=new[]{new Book{Id="b",Title="10",CreatedUtc=a.CreatedUtc},new Book{Id="a",Title="2",CreatedUtc=a.CreatedUtc}};Check(Library.ByCreated(ties,true).First().Title=="2","creation timestamp ties use stable natural name order");
    var archive=scan.Books.First(b=>b.Id==zipPath);archive.Pages[0].ReadInfo();Check(archive.Pages.Count==3&&archive.Pages[0].Name=="chapter/1.png"&&archive.Pages[0].Decode(300).PixelWidth==300,"CBZ natural order and direct decode");
    var missing=Library.Scan(new[]{Path.Combine(directory,"missing")});Check(missing.Books.Count==0&&missing.Warnings.Count==1,"missing source reported without crash");
