    foreach(var format in formats){string file=Path.Combine(directory,"format."+format.Key);format.Value.Frames.Add(original);using(var stream=File.Create(file))format.Value.Save(stream);var p=new Page{Path=file};p.ReadInfo();Check(p.Error==null&&p.Decode(300).PixelWidth==300,format.Key+" format decode");}
    for(int o=2;o<=8;o++){var metadata=new BitmapMetadata("jpg");metadata.SetQuery("/app1/ifd/{ushort=274}",(ushort)o);var encoder=new JpegBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(original,null,metadata,null));string file=Path.Combine(directory,"orientation"+o+".jpg");using(var stream=File.Create(file))encoder.Save(stream);var p=new Page{Path=file};p.ReadInfo();Check(p.Width==(o>=5?900:600)&&p.Decode(300).PixelWidth==300,"EXIF orientation "+o+" dimensions and decode");}
    var settings=new Settings();settings.Roots.Add(root);settings.Books[alpha]=new Progress{Page=11,Mode=2,Fraction=.37,Bookmarks=new List<int>{3,11}};Check(settings.Save()==null,"atomic settings save");var restored=Settings.Load();Check(restored.Get(a).Page==11&&restored.Get(a).Mode==2&&restored.Get(a).Bookmarks.Contains(11),"progress, reading direction and bookmarks survive reload");restored.Get(a).Page=999;Check(restored.Get(a).Page==15,"deleted pages clamp saved progress");
    settings.Books.Clear();settings.ShelfSort=3;settings.Save();window=new MainWindow(true,new string[0]);window.WindowStartupLocation=WindowStartupLocation.Manual;window.Left=-20000;window.Top=-20000;window.Width=1220;window.Height=820;window.Show();window.SetTestBooks(scan.Books);Check(window.ShelfSortControl.SelectedIndex==3,"creation sorting preference restored on startup");window.ShelfSortControl.SelectedIndex=4;window.State.Save();Check(Settings.Load().ShelfSort==4,"changed shelf sort persists");window.ShelfSortControl.SelectedIndex=3;await Task.Delay(1000);Screenshot(window,Path.Combine(directory,"01-bookshelf.png"));
    await window.OpenBook(a);window.Reader.SetMode(1);window.Reader.Jump(10);window.Reader.Nudge(1);Check(window.Reader.Progress.Page==11&&window.Reader.VisibleCount==2,"live reader nudge shows 12-13");window.Reader.Turn(1);Check(window.Reader.Progress.Page==13,"live reader next shows 14-15");window.Reader.Turn(-1);Check(window.Reader.Progress.Page==11,"live reader previous returns 12-13");await Task.Delay(600);Screenshot(window,Path.Combine(directory,"02-spread-ltr.png"));
