    var slider=window.PageProgressControl;window.UpdateLayout();slider.ApplyTemplate();var track=(Track)slider.Template.FindName("PART_Track",slider);
    Check(slider.IsDirectionReversed&&track.ValueFromPoint(new Point(0,0))>track.ValueFromPoint(new Point(track.ActualWidth,0)),"RTL progress physically maps later pages to the left");
    slider.Value=5;Check(window.Reader.Progress.Page==4,"RTL slider value jumps to the correct actual page");window.Reader.Jump(11);
    window.State.Save();var savedSpread=Settings.Load();window.Reader.Open(a,savedSpread.Get(a));window.Reader.Turn(1);window.Reader.Turn(-1);Check(window.Reader.Progress.Page==11,"spread pairing anchor survives application state reload");
    window.Reader.RaiseEvent(new MouseWheelEventArgs(Mouse.PrimaryDevice,Environment.TickCount,-120){RoutedEvent=Mouse.MouseWheelEvent});Check(window.Reader.Progress.Page==13,"wheel down moves forward in RTL");
    window.Reader.SetMode(0);window.Reader.Jump(7);Check(window.Reader.VisibleCount==1,"single image mode live");window.UpdateLayout();Check(!slider.IsDirectionReversed&&track.ValueFromPoint(new Point(0,0))<track.ValueFromPoint(new Point(track.ActualWidth,0)),"single-page mode restores left-to-right progress");await Task.Delay(300);Screenshot(window,Path.Combine(directory,"04-single.png"));
    var toon=scan.Books.First(b=>b.Id==nested);await window.OpenBook(toon);window.Reader.SetMode(3);window.Reader.Jump(2);window.Reader.Scroll(200);Check(window.Reader.Progress.Page==2&&window.Reader.Progress.Fraction>0,"webtoon stores position within tall page");double fraction=window.Reader.Progress.Fraction;window.Reader.SetZoom(1.2);Check(Math.Abs(window.Reader.Progress.Fraction-fraction)<.001,"webtoon zoom preserves reading anchor");await Task.Delay(600);Screenshot(window,Path.Combine(directory,"05-webtoon.png"));
    window.Reader.SetOffset(double.MaxValue);Check(Math.Abs(window.Reader.Offset-Math.Max(0,window.Reader.Extent-window.Reader.ActualHeight))<1,"webtoon lower scroll boundary");window.Reader.SetOffset(-100);Check(window.Reader.Offset==0,"webtoon upper scroll boundary");
