    window.Reader.Jump(2);window.Reader.Scroll(150);int savedPage=window.Reader.Progress.Page;double savedFraction=window.Reader.Progress.Fraction;window.State.Save();var reload=Settings.Load();window.Reader.Open(toon,reload.Get(toon));Check(window.Reader.Progress.Page==savedPage&&Math.Abs(window.Reader.Progress.Fraction-savedFraction)<.001,"actual webtoon page and in-page position reopen");
    Check(!slider.IsDirectionReversed,"webtoon restores normal page progress direction");
    window.ReadingActivity(true);await Task.Delay(3300);Check(window.ReadingUiHidden,"reading UI automatically hides after three idle seconds");window.UpdateLayout();Check(window.Reader.Progress.Page==savedPage&&Math.Abs(window.Reader.Progress.Fraction-savedFraction)<.001,"webtoon reading anchor remains stable when UI hides");Screenshot(window,Path.Combine(directory,"07-idle-hidden.png"));
