    Key(window,System.Windows.Input.Key.F11);Check(window.WindowStyle==WindowStyle.None,"fullscreen enters without chrome");Key(window,System.Windows.Input.Key.Escape);Check(window.WindowStyle!=WindowStyle.None&&window.Reader.Book!=null,"escape exits fullscreen while keeping book open");window.Left=-20000;window.Top=-20000;
    Key(window,System.Windows.Input.Key.F11);window.ReadingPointerAt(new Point(400,10));Check(!window.ReadingUiHidden&&window.WindowStyle==WindowStyle.None,"fullscreen edge reveals controls without leaving fullscreen");Key(window,System.Windows.Input.Key.Escape);window.Left=-20000;window.Top=-20000;
