    bool overlap=false;for(int i=0;i<rectangles.Length;i++)for(int j=i+1;j<rectangles.Length;j++)if(rectangles[i].IntersectsWith(rectangles[j]))overlap=true;Check(!overlap,"gridShelf card rectangles never overlap");Screenshot(window,Path.Combine(directory,"08-continuous-grid.png"));
