    string panoramaPath=Path.Combine(directory,"panorama.png");Art(panoramaPath,1,1800,300,Color.FromRgb(40,110,90));var panorama=new Page{Path=panoramaPath};panorama.ReadInfo();window.Width=2200;window.Height=1400;window.SetTestBooks(Enumerable.Range(0,240).Select(i=>new Book{Id="wide-shelf-"+i,Title="横图 "+i,Pages=new List<Page>{panorama}}).ToList());await Task.Delay(200);for(int i=0;i<100&&!gridShelf.VisibleCoversReady;i++)await Task.Delay(100);Check(gridShelf.RealizedCount<120&&gridShelf.VisibleCoversReady,"large viewport loads all visible covers with bounded realization (realized="+gridShelf.RealizedCount+", ready="+gridShelf.VisibleCoversReady+")");
